182: 	private static function delta_html( $a, $b, $pp = false, $atv = false ) {
183: 		if ( null === $a || null === $b || 0 == $b ) { return '<span class="psr-delta neut">—</span>'; }
184: 		$d  = $a - $b;
185: 		$sk = $pp ? $d : $d / abs( $b ) * 100;
186: 		if ( abs( $sk ) < 0.05 ) { return '<span class="psr-delta neut">— 0,0 ' . ( $pp ? 'p.p.' : '%' ) . '</span>'; }
187: 		$ger = ( $sk > 0 ) ? ! $atv : $atv;
188: 		return '<span class="psr-delta ' . ( $ger ? 'up' : 'down' ) . '">' . ( $sk > 0 ? '▲' : '▼' ) . ' '
189: 			. number_format( abs( $sk ), 1, ',', ' ' ) . ( $pp ? ' p.p.' : ' %' ) . '</span>';
190: 	}
