208: 	/** 7 d. suma vs vidurkis 4 ankstesnių 7-dienių langų. Grąžina [dabar, bazinė, pokytis %] arba null. */
209: 	private static function bazine( $m, $k, $nuo ) {
210: 		$pakanka = ( $nuo <= self::pries_d( 34 ) );
211: 		if ( ! $pakanka ) { return null; }
212: 		$dab = 0; $baz = 0;
213: 		for ( $i = 0; $i < 35; $i++ ) {
214: 			$d = self::pries_d( $i ); $v = isset( $m[ $d ] ) ? (float) $m[ $d ][ $k ] : 0;
215: 			if ( $i < 7 ) { $dab += $v; } else { $baz += $v; }
216: 		}
217: 		$baz = $baz / 4;
218: 		if ( $baz <= 0 ) { return null; }
219: 		return array( $dab, $baz, ( $dab - $baz ) / $baz * 100 );
220: 	}
